    if resources:
        target = min(resources, key=lambda r: dist((x,y), (r['x'],r['y'])))
    elif opponents:
        target = opponents
    if target:
        if isinstance(target, list):
            ox, oy = target
        else:
            ox, oy = target['x'], target['y']
        dx = (ox - x)
        dy = (oy - y)
        dx = (dx > 0) - (dx < 0)
        dy = (dy > 0) - (dy < 0)
        for move in safe_moves((x,y)):
            if move == (dx,dy):
                return [dx, dy]
        if safe_moves((x,y)):
            return safe_moves((x,y))[0]
    if safe_moves((x,y)):
        return safe_moves((x,y))[0]
    return [0,0]
